import{_ as a,o as d,c as e,a2 as l}from"./chunks/framework.1lR7qgqY.js";const k=JSON.parse('{"title":"K5 工具呼叫, MCP 與代理","description":"","frontmatter":{},"headers":[],"relativePath":"know/k5-tools-agents.md","filePath":"know/k5-tools-agents.md","lastUpdated":null}'),r={name:"know/k5-tools-agents.md"};function o(i,t,n,h,s,c){return d(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="k5-工具呼叫-mcp-與代理" tabindex="-1">K5 工具呼叫, MCP 與代理 <a class="header-anchor" href="#k5-工具呼叫-mcp-與代理" aria-label="Permalink to &quot;K5 工具呼叫, MCP 與代理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (K5.1 至 K5.3 僅有大綱)</li><li>待查證: BFCL 分數取自彙整站 benchmarklist.com, 應改連官方排行榜</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 模型本身不會「動手」, 它只會輸出「要呼叫哪個工具, 帶什麼參數」, 由程式去執行. 多數情境不需要代理框架, 以「固定步驟的工作流程程式碼 + 每步一次函式呼叫 + 程式端驗證」取得的可靠度最高 (信心: 中高). MCP 是讓多個客戶端共用同一組工具的標準協定, 代理則是讓模型自己決定下一步; 兩者都屬於符合特定條件才用的元件.</p><h2 id="k5-1-單步準確率與多輪可靠度的差別" tabindex="-1">K5.1 單步準確率與多輪可靠度的差別 <a class="header-anchor" href="#k5-1-單步準確率與多輪可靠度的差別" aria-label="Permalink to &quot;K5.1 單步準確率與多輪可靠度的差別&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>單步選對函式與填對參數, 和多輪串接任務是兩種能力</li><li>BFCL V4 的分項說明</li></ul><h2 id="k5-2-bfcl-分數的讀法與限制" tabindex="-1">K5.2 BFCL 分數的讀法與限制 <a class="header-anchor" href="#k5-2-bfcl-分數的讀法與限制" aria-label="Permalink to &quot;K5.2 BFCL 分數的讀法與限制&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>彙整站與官方排行榜的差異</li><li>模型卡自報分數與獨立評測的差異</li></ul><h2 id="k5-3-用自己的任務做-20-題實測" tabindex="-1">K5.3 用自己的任務做 20 題實測 <a class="header-anchor" href="#k5-3-用自己的任務做-20-題實測" aria-label="Permalink to &quot;K5.3 用自己的任務做 20 題實測&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>設計 20 題工具呼叫測試</li><li>併入 M6 的回歸測試集</li></ul><h2 id="k5-4-先寫工作流程-再考慮代理" tabindex="-1">K5.4 先寫工作流程, 再考慮代理 <a class="header-anchor" href="#k5-4-先寫工作流程-再考慮代理" aria-label="Permalink to &quot;K5.4 先寫工作流程, 再考慮代理&quot;">​</a></h2><p>小模型「選對函式, 填對參數」的單步準確率約 78% 至 88%, 但多輪任務只有約 30% 至 42%.</p><table tabindex="0"><thead><tr><th>模型</th><th>總分</th><th>非即時 AST</th><th>即時 (Live)</th><th>多輪 (Multi-turn)</th></tr></thead><tbody><tr><td>Qwen3-8B (FC)</td><td>42.57%</td><td>87.58%</td><td>80.53%</td><td>41.75%</td></tr><tr><td>Qwen3-14B (FC)</td><td>41.03%</td><td>84.94%</td><td>80.01%</td><td>34.75%</td></tr><tr><td>Qwen3-30B-A3B-Instruct-2507 (FC)</td><td>41.39%</td><td>85.77%</td><td>77.94%</td><td>30%</td></tr><tr><td>Qwen3.5-4B (模型卡自報)</td><td>50.3%</td><td>-</td><td>-</td><td>-</td></tr></tbody></table><p>資料來源: BFCL V4 (Berkeley Function Calling Leaderboard), 經 benchmarklist.com 彙整, 資料匯入日 2026-05-28; Qwen3.5-4B 為模型卡自報.</p><p>讓 8B 模型自主串接 5 步以上的工具, 失敗是常態 (信心: 中高). 另有一篇論文 (arXiv 2608.22472) 顯示, 改用「指令遵循式」函式呼叫格式, 可讓 Qwen3-4B 與 8B 在 BFCL 子集提升到 90% 以上, 表示提示格式與流程設計的影響可能大於換框架 (信心: 中).</p><h2 id="k5-5-函式呼叫與-mcp-的取捨" tabindex="-1">K5.5 函式呼叫與 MCP 的取捨 <a class="header-anchor" href="#k5-5-函式呼叫與-mcp-的取捨" aria-label="Permalink to &quot;K5.5 函式呼叫與 MCP 的取捨&quot;">​</a></h2><p>MCP (Model Context Protocol) 最新規格是 2026-07-28 版, 核心改為無狀態, 取消 initialize 交握與 Mcp-Session-Id 標頭, 並新增正式的棄用政策 (12 個月棄用期). 美國 NSA 於 2026-06-02 發布 MCP 安全設計指引.</p><table tabindex="0"><thead><tr><th>情境</th><th>建議</th></tr></thead><tbody><tr><td>自己撰寫的單一應用, 工具不超過 3 至 5 個, 只有一個客戶端</td><td>直接用函式呼叫</td></tr><tr><td>同一組工具要給多個客戶端共用 (Open WebUI, IDE, 桌面助理)</td><td>使用 MCP</td></tr><tr><td>要使用信譽良好的現成伺服器</td><td>使用 MCP, 並依 M7.1 節審核</td></tr><tr><td>低階硬體的初階讀者</td><td>不建議列為入門步驟</td></tr></tbody></table><p>不建議初階讀者的理由有三: 小模型多輪工具呼叫可靠度低; 每個 MCP 伺服器都是以使用者權限執行的程式; 一般函式呼叫就能完成同樣的事 (信心: 中高). 手冊範例須標註所依據的 MCP 規格版本.</p>',21)])])}const u=a(r,[["render",o]]);export{k as __pageData,u as default};
